		const validDiff = [
			'diff --git a/src/a.ts b/src/a.ts',
			'--- a/src/a.ts',
			'+++ b/src/a.ts',
			'@@ -1,2 +1,2 @@',
			' line1',
			'-old',
			'+new',
		].join('\n');
		const accepted: UniverseAgentWriteGitWriteResult = {
			supported: true, reason: '', success: true, errorMessage: '', exitCode: 0, stdout: '',
		};
